getM64 :: StablePtr Object -> IO (M.Matrix Double)
getM64 pointer = do
 value <- deRefStablePtr pointer
 case value of
  M64 x -> pure x
  _ -> fail "dense object kind/precision mismatch"

getL64 :: StablePtr Object -> IO (L.LU Double)
getL64 pointer = do
 value <- deRefStablePtr pointer
 case value of
  L64 x -> pure x
  _ -> fail "dense object kind/precision mismatch"

getQ64 :: StablePtr Object -> IO (Q.QR Double)
getQ64 pointer = do
 value <- deRefStablePtr pointer
 case value of
  Q64 x -> pure x
  _ -> fail "dense object kind/precision mismatch"

foreign export ccall "hm_dense_values_f64" values64 :: StablePtr Object -> Ptr CDouble -> IO CInt
values64 :: StablePtr Object -> Ptr CDouble -> IO CInt
values64 pointer out = boundary $ do
 object <- deRefStablePtr pointer
 let values = case object of
       M64 m -> M.toList m
       V64 xs -> xs
       _ -> error "dense values kind/precision mismatch"
 strict <- mapM evaluate values
 checked (Right ()) (const (pokeArray (castPtr out :: Ptr Double) strict))

