ffiHmDenseFromListF64 a0 a1 a2 a2Count out = boundary $ do
 let a0Value = fromIntegral a0
 let a1Value = fromIntegral a1
 a2Value <- peekArray (fromIntegral a2Count) (castPtr a2 :: Ptr Double)
 checked (Right (M.fromList a0Value a1Value a2Value) :: Either MathError (Maybe (M.Matrix Double))) $ \value -> publishMaybe M64 value out

