ffiHmDenseAtF64 :: StablePtr Object -> CPtrdiff -> CPtrdiff -> Ptr CDouble -> Ptr CInt -> IO CInt
ffiHmDenseAtF64 a0 a1 a2 out found = boundary $ do
 a0Value <- getM64 a0
 let a1Value = fromIntegral a1
 let a2Value = fromIntegral a2
 checked (Right (M.at a0Value a1Value a2Value) :: Either MathError (Maybe Double)) $ \result -> case result of
  Nothing -> poke found 0
  Just value -> do
   strict <- evaluate value
   poke out (coerce strict :: CDouble)
   poke found 1

